mapper.sql:
WHERE 1=1

  AND (UPPER(T1.SYSTEM_ID) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(T1.SYSTEM_NAME) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.OWNER_ORG,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.SYSTEM_ID = #{systemId}
AND T1.SYSTEM_NAME LIKE '%'||#{systemName}||'%'
AND T1.OWNER_ORG = #{ownerOrg}
AND T1.STATUS_CD = #{statusCd}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.SYSTEM_ID, T1.SYSTEM_NAME, T1.OWNER_ORG, T1.STATUS_CD, T1.REMARK,
           T1.REG_USER_ID, T1.REG_DTM, T1.CHG_USER_ID, T1.CHG_DTM
      FROM TB_IF_BIZ_SYSTEM_PILOT T1

     ORDER BY T1.REG_DTM DESC, T1.SYSTEM_ID ASC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}
